//! Sequential execution of the TOML sweep manifests generated by setup.

use crate::benchmark::BenchmarkConfig;
use crate::runner;
use crate::{Error, compare, read_config};
use serde::Deserialize;
use std::collections::BTreeSet;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

const MAX_SWEEP_BYTES: u64 = 64 * 1024;
const MAX_CONFIGS: usize = 256;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SweepFile {
    configs: Vec<String>,
}

/// Validate and execute every benchmark referenced by a sweep manifest.
pub fn run(
    path: &str,
    json: bool,
    show_output: bool,
    mode: Option<crate::tape::Mode>,
    respect_record_timings: bool,
    cassette_root: Option<&Path>,
    output: &mut dyn Write,
) -> Result<(), Error> {
    let sweep_path = Path::new(path);
    let text = read_sweep(sweep_path)?;
    let value: toml::Value = toml::from_str(&text)
        .map_err(|error| Error::Input(format!("cannot parse sweep {path}: {error}")))?;
    let table = value.as_table().ok_or_else(|| {
        Error::Input(format!(
            "{path} is not a sweep TOML; expected `configs = [...]`"
        ))
    })?;
    if !table.contains_key("configs") {
        return Err(Error::Input(format!(
            "{path} is not a sweep TOML; expected `configs = [...]` (a normal benchmark TOML was supplied)"
        )));
    }
    let sweep: SweepFile = value
        .try_into()
        .map_err(|error| Error::Input(format!("invalid sweep {path}: {error}")))?;
    if sweep.configs.is_empty() {
        return Err(Error::Input(format!(
            "sweep {path} contains no benchmark configurations"
        )));
    }
    if sweep.configs.len() > MAX_CONFIGS {
        return Err(Error::Input(format!(
            "sweep {path} contains {} configurations; the maximum is {MAX_CONFIGS}",
            sweep.configs.len()
        )));
    }
    let parent = sweep_path.parent().unwrap_or_else(|| Path::new("."));
    let stem = sweep_path
        .file_stem()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("sweep");
    let results_root = parent.join(format!("{stem}-results"));
    std::fs::create_dir_all(&results_root).map_err(|error| {
        Error::Run(format!(
            "cannot create sweep results directory {}: {error}",
            results_root.display()
        ))
    })?;

    let mut failures: Vec<(String, Vec<String>)> = Vec::new();
    let warnings = Mutex::new(BTreeSet::new());
    for (index, reference) in sweep.configs.iter().enumerate() {
        let config_path = checked_reference(parent, reference, path)?;
        let config_text = read_config(&config_path)?;
        let config_value: toml::Value = toml::from_str(&config_text).map_err(|error| {
            Error::Input(format!(
                "cannot parse benchmark {}: {error}",
                config_path.display()
            ))
        })?;
        if config_value.get("configs").is_some() {
            add_failure(
                &mut failures,
                config_path.display().to_string(),
                "is a nested sweep; sweep entries must be normal benchmark TOMLs".into(),
            );
            continue;
        }
        let config: BenchmarkConfig = config_value.try_into().map_err(|error| {
            Error::Input(format!(
                "invalid benchmark {}: {error}",
                config_path.display()
            ))
        })?;
        let result_dir = results_root.join(format!("{index:03}-{}", safe_name(&config_path)));
        std::fs::create_dir_all(&result_dir).map_err(|error| {
            Error::Run(format!(
                "cannot create results directory {}: {error}",
                result_dir.display()
            ))
        })?;
        // Resolve the result directory before rendering paths into the
        // isolated config. Otherwise a relative result directory is resolved
        // a second time by the runner, nesting logs/workspaces under the
        // result directory itself.
        let resolved_result_dir = result_dir.canonicalize().map_err(|error| {
            Error::Run(format!(
                "cannot resolve isolated benchmark {}: {error}",
                result_dir.display()
            ))
        })?;
        let isolated = isolated_config(&config, &resolved_result_dir);
        let isolated_path = resolved_result_dir.join("benchmark.toml");
        let serialized = toml::to_string_pretty(&isolated)
            .map_err(|error| Error::Run(format!("cannot render sweep benchmark: {error}")))?;
        std::fs::write(&isolated_path, serialized).map_err(|error| {
            Error::Run(format!("cannot write {}: {error}", isolated_path.display()))
        })?;
        let cassette = cassette_root.map(|root| {
            root.join(format!("{index:03}-{}", safe_name(&config_path)))
                .join("cassettes")
                .join(format!(
                    "benchmark-{}-{}-{}.jsonl",
                    safe_component(&config.agent),
                    safe_component(&config.workload),
                    safe_component(&config.model)
                ))
        });
        if !json {
            write_progress(output, index, sweep.configs.len(), &config_path, &config)?;
        }
        if let Err(error) = runner::run_with_diagnostics(
            isolated_path.to_string_lossy().as_ref(),
            json,
            show_output,
            None,
            mode,
            cassette.as_deref().and_then(|path| path.to_str()),
            respect_record_timings,
            output,
            &warnings,
        ) {
            add_failure(
                &mut failures,
                config_path.display().to_string(),
                error.to_string(),
            );
        }
    }
    // Always regenerate the comparison artifacts after the execution loop,
    // including partial sweeps. The comparison report records missing or
    // failed benchmark entries instead of hiding useful completed results.
    // `--json` promises a stream of one JSON object per line.  Comparison
    // generation still runs, but its human summary must not contaminate that
    // machine-readable stream.
    let comparison_error = if json {
        let mut comparison_output = Vec::new();
        compare::run(path, &mut comparison_output).err()
    } else {
        compare::run(path, output).err()
    };
    if failures.is_empty() {
        comparison_error.map_or(Ok(()), Err)
    } else {
        let mut details = format!(
            "sweep completed with {} failed benchmark(s): {}",
            failures
                .iter()
                .map(|(_, configs)| configs.len())
                .sum::<usize>(),
            failures
                .iter()
                .map(|(error, configs)| format!("{}: {error}", configs.join(", ")))
                .collect::<Vec<_>>()
                .join("; ")
        );
        if let Some(error) = comparison_error {
            details.push_str(&format!("; comparison failed: {error}"));
        }
        Err(Error::Run(details))
    }
}

fn write_progress(
    output: &mut dyn Write,
    index: usize,
    total: usize,
    config_path: &Path,
    config: &BenchmarkConfig,
) -> Result<(), Error> {
    let name = config_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("benchmark");
    // A manifest or model identifier may contain terminal control characters;
    // keep this human-facing status to exactly one safe line.
    let one_line = |value: &str| {
        value
            .chars()
            .map(|ch| if ch.is_control() { ' ' } else { ch })
            .collect::<String>()
    };
    writeln!(
        output,
        "Starting benchmark ({}/{}; {}% reached): {} — {}, {}, {}, {} (concurrency {})",
        index + 1,
        total,
        (index + 1) * 100 / total,
        one_line(name),
        one_line(&config.agent),
        one_line(&config.provider),
        one_line(&config.model),
        one_line(&config.workload),
        config.concurrency,
    )
    .and_then(|_| output.flush())
    .map_err(|error| Error::Io(format!("cannot write sweep progress: {error}")))
}

fn add_failure(failures: &mut Vec<(String, Vec<String>)>, config: String, message: String) {
    if let Some((_, configs)) = failures.iter_mut().find(|(item, _)| *item == message) {
        configs.push(config);
    } else {
        failures.push((message, vec![config]));
    }
}

fn read_sweep(path: &Path) -> Result<String, Error> {
    let metadata = std::fs::metadata(path)
        .map_err(|error| Error::Input(format!("cannot read sweep {}: {error}", path.display())))?;
    if metadata.len() > MAX_SWEEP_BYTES {
        return Err(Error::Input(
            "sweep configuration is larger than 64 KiB".into(),
        ));
    }
    read_config(path)
}

fn checked_reference(parent: &Path, reference: &str, sweep: &str) -> Result<PathBuf, Error> {
    let path = Path::new(reference);
    if path.is_absolute()
        || path
            .components()
            .any(|component| component == std::path::Component::ParentDir)
    {
        return Err(Error::Input(format!(
            "sweep {sweep} contains unsafe benchmark path `{reference}`; use a relative .toml path"
        )));
    }
    if path.extension().and_then(|value| value.to_str()) != Some("toml") {
        return Err(Error::Input(format!(
            "sweep {sweep} entry `{reference}` is not a .toml benchmark"
        )));
    }
    let resolved = parent.join(path);
    if !resolved.is_file() {
        return Err(Error::Input(format!(
            "sweep {sweep} references missing benchmark {}",
            resolved.display()
        )));
    }
    Ok(resolved)
}

fn isolated_config(config: &BenchmarkConfig, result_dir: &Path) -> BenchmarkConfig {
    let mut isolated = config.clone();
    isolated.workspace = result_dir.join("workspace").to_string_lossy().into_owned();
    isolated.log_file = result_dir.join("run.log").to_string_lossy().into_owned();
    if let Some(measurements) = isolated.measurements.as_mut() {
        measurements.directory = result_dir
            .join("measurements")
            .to_string_lossy()
            .into_owned();
    }
    isolated
}

fn safe_name(path: &Path) -> String {
    path.file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("benchmark")
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.') {
                character
            } else {
                '-'
            }
        })
        .collect()
}

fn safe_component(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.') {
                character
            } else {
                '-'
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::{run, write_progress};
    use std::io::Write;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn temp_file(name: &str, contents: &str) -> std::path::PathBuf {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!("asb-sweep-{stamp}"));
        std::fs::create_dir_all(&directory).expect("directory");
        let path = directory.join(name);
        std::fs::write(&path, contents).expect("file");
        path
    }

    #[test]
    fn progress_is_flushed_and_keeps_untrusted_labels_to_one_line() {
        #[derive(Default)]
        struct Capture {
            bytes: Vec<u8>,
            flushed: bool,
        }
        impl Write for Capture {
            fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
                self.bytes.extend_from_slice(bytes);
                Ok(bytes.len())
            }
            fn flush(&mut self) -> std::io::Result<()> {
                self.flushed = true;
                Ok(())
            }
        }
        let mut config: crate::benchmark::BenchmarkConfig =
            toml::from_str("agent='pi'\nworkload='bug-fix'\nprovider='local'\nmodel='model'\n")
                .unwrap();
        config.model = "model\n\u{1b}[31m".into();
        let mut capture = Capture::default();
        write_progress(
            &mut capture,
            1,
            3,
            std::path::Path::new("bad\nname.toml"),
            &config,
        )
        .unwrap();
        let text = String::from_utf8(capture.bytes).unwrap();
        assert!(capture.flushed);
        assert!(text.contains("(2/3; 66% reached): bad name.toml"));
        assert_eq!(text.lines().count(), 1);
        assert!(!text.contains('\u{1b}'));
    }

    #[test]
    fn progress_output_failures_are_reported() {
        struct Broken;
        impl Write for Broken {
            fn write(&mut self, _: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "closed",
                ))
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let config: crate::benchmark::BenchmarkConfig =
            toml::from_str("agent='pi'\nworkload='bug-fix'\nprovider='local'\nmodel='model'\n")
                .unwrap();
        let error = write_progress(
            &mut Broken,
            0,
            1,
            std::path::Path::new("test.toml"),
            &config,
        )
        .unwrap_err();
        assert!(error.to_string().contains("cannot write sweep progress"));
    }

    #[test]
    fn rejects_a_normal_benchmark_as_a_sweep() {
        let path = temp_file(
            "benchmark.toml",
            "agent = \"codex\"\nworkload = \"bug-fix\"\nprovider = \"openrouter\"\nmodel = \"tool-model\"\n",
        );
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("normal benchmark must be rejected");
        assert!(error.to_string().contains("not a sweep TOML"));
    }

    #[test]
    fn rejects_unsafe_references_before_execution() {
        let path = temp_file("sweep.toml", "configs = [\"../benchmark.toml\"]\n");
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("parent traversal must be rejected");
        assert!(error.to_string().contains("unsafe benchmark path"));
    }

    #[test]
    fn regenerates_comparison_after_a_partial_sweep() {
        let path = temp_file("sweep.toml", "configs = [\"benchmark.toml\"]\n");
        let benchmark = path.parent().expect("sweep parent").join("benchmark.toml");
        std::fs::write(
            &benchmark,
            "agent = \"not-installed\"\nworkload = \"bug-fix\"\nprovider = \"local\"\nmodel = \"test-model\"\n",
        )
        .expect("benchmark");
        let error = run(
            path.to_str().expect("path"),
            false,
            false,
            None,
            false,
            None,
            &mut Vec::new(),
        )
        .expect_err("invalid agent leaves a failed sweep");
        assert!(error.to_string().contains("failed benchmark"));
        let report = path
            .parent()
            .expect("parent")
            .join("results/sweep-comparison/report.html");
        assert!(report.is_file(), "automatic comparison report exists");
    }
}
